//删除多余元素，只保留关键词和句子
public void cleanUp(String text) {
    String[] keywords = text.split("：");
    String result = "";
    for (String keyword : keywords) {
        if (!"".equals(keyword)) {
            result += keyword + "：";
        }
    }
    System.out.println(result);
}

//删除多余句子，只保留关键词
public void cleanUp(String text) {
    String[] sentences = text.split("；");
    String result = "";
    for (String sentence : sentences) {
        if (!"".equals(sentence)) {
            for (String keyword : sentence.split("：")) {
                if (!"".equals(keyword)) {
                    result += keyword + "：";
                }
            }
        }
    }
    System.out.println(result);
}

